const d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
const nowStr = new Date().toLocaleTimeString();
const pushLog = (sev, src, text) => {
  const logs = flow.get('secLogs') || [];
  const badgeColor = sev === 'CRITICAL' ? '#dc2626' : (sev === 'WARN' ? '#d97706' : '#0284c7');
  logs.unshift({ time: nowStr, sev, src, text, color: badgeColor });
  if (logs.length > 12) logs.pop();
  flow.set('secLogs', logs);
  return logs;
};

let logs = flow.get('secLogs') || [];

if (d.status === 'offline') {
  logs = pushLog('CRITICAL', 'sensor01', 'Node 1 went OFFLINE (LWT triggered)');
  return [
    null,
    { payload: { bg: '#7f1d1d', bd: '#ef4444', title: 'NODE 1 OFFLINE', sub: `Lost connection · ${nowStr}` } },
    { payload: 'OFFLINE' },
    { payload: logs }
  ];
}

const temp = Number(d.temp);
const door = String(d.door || 'closed').toUpperCase();
const doorS = d.door_open_s || 0;
const alarm = d.alarm || 'NONE';

const lastSeq = flow.get('s1_last_seq');
if (d.fake === true || temp < -20 || temp > 60) {
  logs = pushLog('CRITICAL', 'sensor01', `Implausible/Spoofed reading detected (temp=${temp}C, seq=${d.seq})`);
} else if (lastSeq !== undefined && d.seq <= lastSeq && d.seq > 5) {
  logs = pushLog('WARN', 'sensor01', `Replay or duplicate seq detected (${d.seq} <= ${lastSeq})`);
} else if (lastSeq !== undefined && d.seq > lastSeq + 1) {
  logs = pushLog('WARN', 'sensor01', `Sequence gap: ${lastSeq} -> ${d.seq}`);
}
flow.set('s1_last_seq', d.seq);

const prevAlarm = flow.get('s1_prev_alarm');
if (alarm !== prevAlarm) {
  if (alarm !== 'NONE') {
    logs = pushLog(alarm === 'BREACH' ? 'CRITICAL' : 'WARN', 'sensor01', `Alarm activated: ${alarm} (temp=${temp}C, door=${door})`);
  } else if (prevAlarm) {
    logs = pushLog('INFO', 'sensor01', 'Alarm cleared (normal operation resumed)');
  }
  flow.set('s1_prev_alarm', alarm);
}

let bg = '#064e3b', bd = '#10b981', title = 'COLD-CHAIN SAFE (2–8 °C)', sub = `Temp ${temp.toFixed(2)} °C · Door ${door}`;
if (alarm === 'BREACH') {
  bg = '#7f1d1d'; bd = '#ef4444'; title = 'SECURITY BREACH ACTIVE'; sub = `Buzzer + Red LED locked ON · seq #${d.seq}`;
} else if (alarm === 'TEMP' || temp > 28) {
  bg = '#7f1d1d'; bd = '#f97316'; title = 'OVER-TEMPERATURE ALERT'; sub = `${temp.toFixed(2)} °C exceeds safe limit!`;
} else if (alarm === 'DOOR' || door === 'OPEN') {
  bg = '#78350f'; bd = '#f59e0b'; title = `DOOR OPEN (${doorS} s)`; sub = alarm === 'DOOR' ? 'Door open alarm sounding!' : 'Close vaccine fridge door';
} else if (temp > 8) {
  bg = '#78350f'; bd = '#eab308'; title = 'WARNING: ABOVE 8 °C'; sub = `Current: ${temp.toFixed(2)} °C (warming)`;
}

return [
  { payload: temp },
  { payload: { bg, bd, title, sub: `${sub} · ${nowStr}` } },
  { payload: `${door} (${doorS} s)` },
  { payload: logs }
];

const d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
const nowStr = new Date().toLocaleTimeString();
const pushLog = (sev, src, text) => {
  const logs = flow.get('secLogs') || [];
  const badgeColor = sev === 'CRITICAL' ? '#dc2626' : (sev === 'WARN' ? '#d97706' : '#0284c7');
  logs.unshift({ time: nowStr, sev, src, text, color: badgeColor });
  if (logs.length > 12) logs.pop();
  flow.set('secLogs', logs);
  return logs;
};

let logs = flow.get('secLogs') || [];

if (d.status === 'offline') {
  logs = pushLog('CRITICAL', 'sensor02', 'Node 2 Power Monitor OFFLINE (LWT / battery dead)');
  return [
    { payload: { bg: '#7f1d1d', bd: '#ef4444', title: 'NODE 2 OFFLINE (SR-14 ALERT)', sub: `Power monitor silenced · ${nowStr}` } },
    { payload: 0 },
    { payload: 'OFFLINE' },
    { payload: logs }
  ];
}

const mainsOn = String(d.mains).toLowerCase() === 'on';
const offS = d.off_s || 0;
const prevMains = flow.get('s2_prev_mains');
if (prevMains !== mainsOn) {
  logs = pushLog(mainsOn ? 'INFO' : 'CRITICAL', 'sensor02', mainsOn ? 'Mains power RESTORED' : 'Mains power CUT detected — running on backup');
  flow.set('s2_prev_mains', mainsOn);
}

const bg = mainsOn ? '#064e3b' : '#7f1d1d';
const bd = mainsOn ? '#10b981' : '#ef4444';
const title = mainsOn ? 'MAINS POWER ON (230 V OK)' : `POWER CUT DETECTED (${offS} s)`;
const sub = mainsOn ? `seq #${d.seq} · Node 2 healthy · ${nowStr}` : `Backup battery active · Buzzer sounding · ${nowStr}`;

return [
  { payload: { bg, bd, title, sub } },
  { payload: mainsOn ? 1 : 0 },
  { payload: `seq #${d.seq} (${nowStr})` },
  { payload: logs }
];

const nowStr = new Date().toLocaleTimeString();
const logs = flow.get('secLogs') || [];
const isBreach = msg.payload === 'breach';
logs.unshift({
  time: nowStr,
  sev: isBreach ? 'CRITICAL' : 'INFO',
  src: 'dashboard',
  text: `Operator sent '${msg.payload}' -> campus/sensor01/cmd`,
  color: isBreach ? '#dc2626' : '#0284c7'
});
if (logs.length > 12) logs.pop();
flow.set('secLogs', logs);
return { payload: logs };
